// fontCmapLegacyTables 保存四种Windows旧编码按需解码后的区间表
var fontCmapLegacyTables = [4]fontCmapLegacyTable{
	{data: fontCmapLegacyShiftJISData, count: fontCmapLegacyShiftJISCount, raw: fontCmapLegacyShiftJISRaw},
	{data: fontCmapLegacyPRCData, count: fontCmapLegacyPRCCount, raw: fontCmapLegacyPRCRaw},
	{data: fontCmapLegacyBig5Data, count: fontCmapLegacyBig5Count, raw: fontCmapLegacyBig5Raw},
	{data: fontCmapLegacyWansungData, count: fontCmapLegacyWansungCount, raw: fontCmapLegacyWansungRaw},
}

// fontCmap 保存按XPS和OpenXPS规则选定的只读字符映射
type fontCmap struct {
	platform    uint16
	encoding    uint16
	format      uint16
	data        []byte
	numGlyphs   uint32
	count       uint32
	arrayOffset uint32
}

// fontCmapLegacyRange 保存Unicode和旧编码同时连续递增的映射区间
type fontCmapLegacyRange struct {
	first uint16
	last  uint16
	code  uint16
}

// fontCmapLegacyTable 保存单个旧编码表的压缩负载及按需解码状态
type fontCmapLegacyTable struct {
	data   string
	count  int
	raw    int
	once   sync.Once
	ranges atomic.Pointer[[]fontCmapLegacyRange]
}

// parseFontCmap 校验cmap编码目录并解析优先级最高的字符映射子表，不因缺字或格式限制改选子表
// 入参: data 完整cmap表, numGlyphs 字体字形数量
// 返回: *fontCmap 选定映射, error 损坏数据或不支持的编码及格式
func parseFontCmap(data []byte, numGlyphs uint32) (*fontCmap, error) {
	if len(data) < 4 || numGlyphs == 0 || numGlyphs > 65535 {
		return nil, fmt.Errorf("%w: invalid cmap header or glyph count", ErrInvalid)
	}
	if binary.BigEndian.Uint16(data) != 0 {
		return nil, fmt.Errorf("%w: cmap version", ErrUnsupported)
	}
	n := uint64(binary.BigEndian.Uint16(data[2:]))
	end := 4 + 8*n
	if n == 0 || end > uint64(len(data)) {
		return nil, fmt.Errorf("%w: truncated cmap encoding records", ErrInvalid)
	}
	seen := make(map[[3]uint32]bool)
	best := 11
	var chosen *fontCmap
	for i := uint64(4); i < end; i += 8 {
		platform := binary.BigEndian.Uint16(data[i:])
		encoding := binary.BigEndian.Uint16(data[i+2:])
		offset := uint64(binary.BigEndian.Uint32(data[i+4:]))
		if offset < end || offset+2 > uint64(len(data)) {
			return nil, fmt.Errorf("%w: cmap subtable offset", ErrInvalid)
		}
		sub, language, known, err := fontCmapSubtable(data[offset:])
		if err != nil {
			return nil, err
		}
		if known {
			key := [3]uint32{uint32(platform), uint32(encoding), language}
			if seen[key] {
				return nil, fmt.Errorf("%w: duplicate cmap encoding (%d, %d, %d)", ErrInvalid, platform, encoding, language)
			}
			if language != 0 && platform != 1 {
				return nil, fmt.Errorf("%w: cmap language %d for platform %d encoding %d", ErrInvalid, language, platform, encoding)
			}
			seen[key] = true
		}
		rank := fontCmapPriority(platform, encoding)
		if rank < best {
			best = rank
			chosen = &fontCmap{platform: platform, encoding: encoding, format: binary.BigEndian.Uint16(sub), data: sub, numGlyphs: numGlyphs}
		}
	}
	if chosen == nil {
		return nil, fmt.Errorf("%w: no XPS-compatible cmap encoding", ErrUnsupported)
	}
	if err := chosen.validate(); err != nil {
		return nil, err
	}
	return chosen, nil
}

// fontCmapPriority 返回平台与编码组合的cmap选择优先级
// 入参: platform 平台编号, encoding 编码编号
// 返回: int 优先级，11表示不在选择列表中
func fontCmapPriority(platform, encoding uint16) int {
	if platform == 3 {
		switch encoding {
		case 10:
			return 0
		case 1:
			return 1
		case 5, 4, 3, 2, 0:
			if encoding == 0 {
				return 6
			}
			return 7 - int(encoding)
		}
	}
	if platform == 0 {
		switch encoding {
		case 4, 6:
			return 7
		case 3:
			return 8
		case 0, 1, 2:
			return 9
		}
		return 11
	}
	if platform == 1 && encoding == 0 {
		return 10
	}
	return 11
}

// fontCmapSubtable 检查已知基线子表的头部和长度，不猜测未知格式的布局
// 入参: data 从子表起始处开始的剩余表数据
// 返回: []byte 子表范围, uint32 语言编号, bool 是否为基线格式, error 结构错误
func fontCmapSubtable(data []byte) ([]byte, uint32, bool, error) {
	format := binary.BigEndian.Uint16(data)
	var length, language uint32
	switch format {
	case 0, 2, 4, 6:
		if len(data) < 6 {
			return nil, 0, true, fmt.Errorf("%w: truncated cmap subtable header", ErrInvalid)
		}
		length, language = uint32(binary.BigEndian.Uint16(data[2:])), uint32(binary.BigEndian.Uint16(data[4:]))
		if length < 6 {
			return nil, 0, true, fmt.Errorf("%w: short cmap subtable length", ErrInvalid)
		}
	case 8, 10, 12:
		if len(data) < 12 || binary.BigEndian.Uint16(data[2:]) != 0 {
			return nil, 0, true, fmt.Errorf("%w: invalid extended cmap header", ErrInvalid)
		}
		length, language = binary.BigEndian.Uint32(data[4:]), binary.BigEndian.Uint32(data[8:])
		if length < 12 {
			return nil, 0, true, fmt.Errorf("%w: short extended cmap length", ErrInvalid)
		}
	default:
		return data[:2], 0, false, nil
	}
	if uint64(length) > uint64(len(data)) {
		return nil, 0, true, fmt.Errorf("%w: cmap length exceeds table", ErrInvalid)
	}
	return data[:length], language, true, nil
}

// validate 校验选中cmap子表的全部结构与可达字形范围
// 返回: error 子表结构或字形编号错误
func (c *fontCmap) validate() error {
	d := c.data
	switch c.format {
	case 0:
		if len(d) != 262 {
			return fmt.Errorf("%w: cmap format 0 length", ErrInvalid)
		}
		for _, glyph := range d[6:] {
			if uint32(glyph) >= c.numGlyphs {
				return fmt.Errorf("%w: cmap glyph outside maxp", ErrInvalid)
			}
		}
	case 2:
		if err := c.validate2(); err != nil {
			return err
		}
	case 4:
		if err := c.validate4(); err != nil {
			return err
		}
	case 6, 10:
		var start, count uint64
		limit := uint64(1) << 32
		if c.format == 6 {
			if len(d) < 10 {
				return fmt.Errorf("%w: cmap format 6 header", ErrInvalid)
			}
			start, count = uint64(binary.BigEndian.Uint16(d[6:])), uint64(binary.BigEndian.Uint16(d[8:]))
			c.arrayOffset, limit = 10, 1<<16
		} else {
			if len(d) < 20 {
				return fmt.Errorf("%w: cmap format 10 header", ErrInvalid)
			}
			start, count = uint64(binary.BigEndian.Uint32(d[12:])), uint64(binary.BigEndian.Uint32(d[16:]))
			c.arrayOffset = 20
		}
		if start+count > limit || uint64(c.arrayOffset)+2*count != uint64(len(d)) {
			return fmt.Errorf("%w: cmap trimmed array range", ErrInvalid)
		}
		c.count = uint32(count)
		for i := uint64(c.arrayOffset); i < uint64(len(d)); i += 2 {
			if uint32(binary.BigEndian.Uint16(d[i:])) >= c.numGlyphs {
				return fmt.Errorf("%w: cmap glyph outside maxp", ErrInvalid)
			}
		}
	case 8, 12:
		return c.validateGroups()
	default:
		return fmt.Errorf("%w: cmap format %d", ErrUnsupported, c.format)
	}
	if c.format == 2 || c.format == 4 {
		for code := uint32(0); code <= 0xffff; code++ {
			if uint32(c.lookup(code)) >= c.numGlyphs {
				return fmt.Errorf("%w: cmap glyph outside maxp at code %X", ErrInvalid, code)
			}
		}
	}
	return nil
}

// validate2 校验混合单字节和双字节映射的相对偏移及子头范围
// 返回: error 格式2结构错误
func (c *fontCmap) validate2() error {
	d := c.data
	if len(d) < 526 || len(d)%2 != 0 {
		return fmt.Errorf("%w: cmap format 2 header", ErrInvalid)
	}
	var maximum uint32
	for i := 6; i < 518; i += 2 {
		key := uint32(binary.BigEndian.Uint16(d[i:]))
		if key%8 != 0 {
			return fmt.Errorf("%w: cmap subheader key alignment", ErrInvalid)
		}
		maximum = max(maximum, key)
	}
	c.arrayOffset = 518 + maximum + 8
	if uint64(c.arrayOffset) > uint64(len(d)) {
		return fmt.Errorf("%w: cmap subheaders exceed length", ErrInvalid)
	}
	for i := uint32(518); i < c.arrayOffset; i += 8 {
		first := uint32(binary.BigEndian.Uint16(d[i:]))
		count := uint32(binary.BigEndian.Uint16(d[i+2:]))
		offset := uint32(binary.BigEndian.Uint16(d[i+6:]))
		if first > 255 || first+count > 256 || offset%2 != 0 {
			return fmt.Errorf("%w: cmap subheader range", ErrInvalid)
		}
		if count != 0 && (i+6+offset < c.arrayOffset || uint64(i+6+offset)+2*uint64(count) > uint64(len(d))) {
			return fmt.Errorf("%w: cmap subheader glyph array offset", ErrInvalid)
		}
	}
	return nil
}

// validate4 校验格式4有序分段、搜索参数及相对偏移字形数组
// 返回: error 格式4结构错误
func (c *fontCmap) validate4() error {
	d := c.data
	if len(d) < 16 || len(d)%2 != 0 {
		return fmt.Errorf("%w: cmap format 4 header", ErrInvalid)
	}
	n2 := uint32(binary.BigEndian.Uint16(d[6:]))
	n := n2 / 2
	if n == 0 || n2%2 != 0 || 16+8*n > uint32(len(d)) {
		return fmt.Errorf("%w: cmap segment count", ErrInvalid)
	}
	selector := uint32(bits.Len32(n) - 1)
	search := uint32(2) << selector
	if uint32(binary.BigEndian.Uint16(d[8:])) != search || uint32(binary.BigEndian.Uint16(d[10:])) != selector || uint32(binary.BigEndian.Uint16(d[12:])) != n2-search || binary.BigEndian.Uint16(d[14+2*n:]) != 0 {
		return fmt.Errorf("%w: cmap segment search fields or reserved padding", ErrInvalid)
	}
	c.count, c.arrayOffset = n, 16+8*n
	var previous uint32
	for i := uint32(0); i < n; i++ {
		end := uint32(binary.BigEndian.Uint16(d[14+2*i:]))
		start := uint32(binary.BigEndian.Uint16(d[16+2*n+2*i:]))
		word := 16 + 6*n + 2*i
		offset := uint32(binary.BigEndian.Uint16(d[word:]))
		if start > end || i != 0 && start <= previous || offset%2 != 0 {
			return fmt.Errorf("%w: cmap segment ordering or alignment", ErrInvalid)
		}
		if offset != 0 && (word+offset < c.arrayOffset || uint64(word+offset)+2*uint64(end-start+1) > uint64(len(d))) {
			return fmt.Errorf("%w: cmap segment glyph array offset", ErrInvalid)
		}
		previous = end
	}
	if previous != 0xffff {
		return fmt.Errorf("%w: cmap missing terminal segment", ErrInvalid)
	}
	return nil
}

// validateGroups 校验格式8和12的有序非重叠分组及字形编号范围
// 返回: error 分组结构或格式8编码宽度错误
func (c *fontCmap) validateGroups() error {
	d := c.data
	c.arrayOffset = 16
	if c.format == 8 {
		c.arrayOffset = 8208
	}
	if uint64(len(d)) < uint64(c.arrayOffset) {
		return fmt.Errorf("%w: truncated cmap groups header", ErrInvalid)
	}
	c.count = binary.BigEndian.Uint32(d[c.arrayOffset-4:])
	if uint64(c.arrayOffset)+12*uint64(c.count) != uint64(len(d)) {
		return fmt.Errorf("%w: cmap group count or length", ErrInvalid)
	}
	var previous uint32
	for i := uint32(0); i < c.count; i++ {
		pos := uint64(c.arrayOffset) + 12*uint64(i)
		start, end := binary.BigEndian.Uint32(d[pos:]), binary.BigEndian.Uint32(d[pos+4:])
		glyph := binary.BigEndian.Uint32(d[pos+8:])
		if start > end || i != 0 && start <= previous || uint64(glyph)+uint64(end)-uint64(start) >= uint64(c.numGlyphs) {
			return fmt.Errorf("%w: cmap group order or glyph range", ErrInvalid)
		}
		if c.format == 8 {
			if start <= 0xffff && !c.is32(0) {
				for code, last := start, min(end, 0xffff); code <= last; code++ {
					if c.is32(code) {
						return fmt.Errorf("%w: cmap format 8 standalone code is a leading word", ErrInvalid)
					}
				}
			}
			if end > 0xffff {
				for high, last := max(start>>16, 1), end>>16; high <= last; high++ {
					if !c.is32(high) {
						return fmt.Errorf("%w: cmap format 8 missing leading-word bit", ErrInvalid)
					}
				}
			}
		}
		previous = end
	}
	return nil
}

// is32 查询格式8按最高有效位优先排列的前导字位图
// 入参: word 16位编码字
// 返回: bool 是否为32位编码的高字
func (c *fontCmap) is32(word uint32) bool {
	return c.data[12+word/8]&(1<<(7-word%8)) != 0
}

// glyph 将选中编码的原始数值映射为字形编号，缺字返回0且不切换子表
// 入参: code 所选编码中的字符数值
// 返回: uint16 字形编号, error 未初始化的映射或非法字形
func (c *fontCmap) glyph(code uint32) (uint16, error) {
	if c == nil || len(c.data) < 2 || c.numGlyphs == 0 {
		return 0, fmt.Errorf("%w: uninitialized cmap", ErrInvalid)
	}
	glyph := c.lookup(code)
	if uint32(glyph) >= c.numGlyphs {
		return 0, fmt.Errorf("%w: cmap glyph outside maxp", ErrInvalid)
	}
	return glyph, nil
}

// unicodeGlyph 将Unicode标量转换为选中cmap编码并查找字形，缺字返回0且不改选子表
// 入参: r Unicode标量值
// 返回: uint16 字形编号，缺字为0, error 非法标量或未初始化映射为ErrInvalid，未知编码或格式8编码冲突为ErrUnsupported
func (c *fontCmap) unicodeGlyph(r rune) (uint16, error) {
	if !utf8.ValidRune(r) {
		return 0, fmt.Errorf("%w: invalid Unicode scalar %U", ErrInvalid, r)
	}
	if c == nil || len(c.data) < 2 || c.numGlyphs == 0 {
		return 0, fmt.Errorf("%w: uninitialized cmap", ErrInvalid)
	}
	code := uint32(r)
	switch {
	case c.platform == 0 || c.platform == 3 && (c.encoding == 1 || c.encoding == 10):
		if c.format == 8 {
			if r > 0xffff {
				hi, lo := utf16.EncodeRune(r)
				code = uint32(hi)<<16 | uint32(lo)
			} else if c.is32(0) || c.is32(code) {
				return 0, fmt.Errorf("%w: cmap format 8 leading-word bitmap conflicts with standalone UTF-16 code %U", ErrUnsupported, r)
			}
		}
		return c.glyph(code)
	case c.platform == 3 && c.encoding == 0:
		glyph, err := c.glyph(code)
		if err != nil || glyph != 0 || code < 0x20 || code > 0xff {
			return glyph, err
		}
		return c.glyph(code + 0xf000)
	case c.platform == 3 && c.encoding >= 2 && c.encoding <= 5:
		code, mapped := fontCmapLegacyCode(r, c.encoding)
		if !mapped {
			return 0, nil
		}
		return c.glyph(code)
	case c.platform == 1 && c.encoding == 0:
		if code < 0x80 {
			return c.glyph(code)
		}
		for i, scalar := range fontCmapMacRoman {
			if r == scalar {
				return c.glyph(uint32(i) + 0x80)
			}
		}
		return 0, nil
	default:
		return 0, fmt.Errorf("%w: Unicode conversion for cmap platform %d encoding %d", ErrUnsupported, c.platform, c.encoding)
	}
}

// lookup 在已完成结构校验的子表内查找编码，不分配内存
// 入参: code 原始编码数值
// 返回: uint16 字形编号，未映射时为0
func (c *fontCmap) lookup(code uint32) uint16 {
	d := c.data
	switch c.format {
	case 0:
		if code < 256 {
			return uint16(d[6+code])
		}
	case 2:
		if code > 0xffff {
			return 0
		}
		var key uint32
		if code < 256 {
			if binary.BigEndian.Uint16(d[6+2*code:]) != 0 {
				return 0
			}
		} else {
			key = uint32(binary.BigEndian.Uint16(d[6+2*(code>>8):]))
			if key == 0 {
				return 0
			}
		}
		pos, low := 518+key, code&255
		first := uint32(binary.BigEndian.Uint16(d[pos:]))
		count := uint32(binary.BigEndian.Uint16(d[pos+2:]))
		if low < first || low-first >= count {
			return 0
		}
		offset := uint32(binary.BigEndian.Uint16(d[pos+6:]))
		glyph := binary.BigEndian.Uint16(d[pos+6+offset+2*(low-first):])
		if glyph != 0 {
			glyph += binary.BigEndian.Uint16(d[pos+4:])
		}
		return glyph
	case 4:
		if code > 0xffff {
			return 0
		}
		lo, hi := uint32(0), c.count
		for lo < hi {
			mid := lo + (hi-lo)/2
			if uint32(binary.BigEndian.Uint16(d[14+2*mid:])) < code {
				lo = mid + 1
			} else {
				hi = mid
			}
		}
		start := uint32(binary.BigEndian.Uint16(d[16+2*c.count+2*lo:]))
		if code < start {
			return 0
		}
		delta := binary.BigEndian.Uint16(d[16+4*c.count+2*lo:])
		word := 16 + 6*c.count + 2*lo
		offset := uint32(binary.BigEndian.Uint16(d[word:]))
		if offset == 0 {
			return uint16(code) + delta
		}
		glyph := binary.BigEndian.Uint16(d[word+offset+2*(code-start):])
		if glyph != 0 {
			glyph += delta
		}
		return glyph
	case 6, 10:
		var start uint32
		if c.format == 6 {
			start = uint32(binary.BigEndian.Uint16(d[6:]))
		} else {
			start = binary.BigEndian.Uint32(d[12:])
		}
		if code >= start && code-start < c.count {
			return binary.BigEndian.Uint16(d[uint64(c.arrayOffset)+2*uint64(code-start):])
		}
	case 8, 12:
		if c.format == 8 && (code > 0xffff && !c.is32(code>>16) || code <= 0xffff && !c.is32(0) && c.is32(code)) {
			return 0
		}
		lo, hi := uint32(0), c.count
		for lo < hi {
			mid := lo + (hi-lo)/2
			pos := uint64(c.arrayOffset) + 12*uint64(mid)
			if binary.BigEndian.Uint32(d[pos+4:]) < code {
				lo = mid + 1
			} else {
				hi = mid
			}
		}
		if lo != c.count {
			pos := uint64(c.arrayOffset) + 12*uint64(lo)
			start := binary.BigEndian.Uint32(d[pos:])
			if code >= start {
				return uint16(binary.BigEndian.Uint32(d[pos+8:]) + code - start)
			}
		}
	}
	return 0
}

// load 按需解压并返回当前编码的只读区间表
// 返回: []fontCmapLegacyRange 有序映射区间
func (t *fontCmapLegacyTable) load() []fontCmapLegacyRange {
	if cached := t.ranges.Load(); cached != nil {
		return *cached
	}
	t.once.Do(func() {
		decoded := decodeFontCmapLegacy(t.data, t.count, t.raw)
		t.ranges.Store(&decoded)
	})
	return *t.ranges.Load()
}

// decodeFontCmapLegacy 解压列式差分编码的旧编码映射区间
// 入参: data Base64编码的Deflate数据, count 区间总数, rawLen 解压字节数
// 返回: []fontCmapLegacyRange 有序映射区间
func decodeFontCmapLegacy(data string, count, rawLen int) []fontCmapLegacyRange {
	reader := flate.NewReader(base64.NewDecoder(base64.RawStdEncoding, strings.NewReader(data)))
	defer reader.Close()
	raw := make([]byte, rawLen)
	if _, err := io.ReadFull(reader, raw); err != nil {
		panic(err)
	}
	ranges := make([]fontCmapLegacyRange, count)
	pos := 0
	prev := uint32(0x80)
	hiOff := rawLen - 2*count
	loOff := rawLen - count
	for i := range ranges {
		tag, n := binary.Uvarint(raw[pos:])
		pos += n
		df := uint32(tag >> 1)
		var span uint32
		if tag&1 != 0 {
			extra, m := binary.Uvarint(raw[pos:])
			pos += m
			span = uint32(extra) + 1
		}
		first := prev + df
		last := first + span
		code := uint16(raw[hiOff+i])<<8 | uint16(raw[loOff+i])
		ranges[i] = fontCmapLegacyRange{first: uint16(first), last: uint16(last), code: code}
		prev = last + 1
	}
	return ranges
}

// fontCmapLegacyCode 将Unicode标量无损转换为指定Windows旧编码，不采用近似或替代字符
// 入参: r Unicode标量, encoding 平台3的编码编号
// 返回: uint32 单字节或高字节在前的双字节编码, bool 是否可无损映射
func fontCmapLegacyCode(r rune, encoding uint16) (uint32, bool) {
	if r < 0 || r > 0xffff || r >= 0xd800 && r <= 0xdfff || encoding < 2 || encoding > 5 {
		return 0, false
	}
	if r < 0x80 {
		return uint32(r), true
	}
	table := fontCmapLegacyTables[encoding-2].load()
	scalar := uint16(r)
	low, high := 0, len(table)
	for low < high {
		mid := int(uint(low+high) >> 1)
		if table[mid].last < scalar {
			low = mid + 1
		} else {
			high = mid
		}
	}
	if low == len(table) || scalar < table[low].first {
		return 0, false
	}
	return uint32(table[low].code) + uint32(scalar-table[low].first), true
}
